package com.abhishek.ecommerce.gateway;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.filter.GatewayFilterChain; import org.springframework.cloud.gateway.filter.GlobalFilter; import org.springframework.core.Ordered; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets;
@Component public class JwtGatewayFilter implements GlobalFilter, Ordered { private final SecretKey key; public JwtGatewayFilter(@Value("${app.jwt.secret}") String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public Mono<Void> filter(ServerWebExchange ex,GatewayFilterChain chain){String p=ex.getRequest().getURI().getPath();if(p.startsWith("/api/users/register")||p.startsWith("/api/users/login")||p.startsWith("/actuator"))return chain.filter(ex);String h=ex.getRequest().getHeaders().getFirst("Authorization");if(h==null||!h.startsWith("Bearer ")){ex.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return ex.getResponse().setComplete();}try{var c=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();var req=ex.getRequest().mutate().header("X-User-Id",c.getSubject()).header("X-User-Role",String.valueOf(c.get("role"))).build();return chain.filter(ex.mutate().request(req).build());}catch(Exception e){ex.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);return ex.getResponse().setComplete();}} public int getOrder(){return -100;} }